<?php
// Session-level rights for bridge tokens (dev/docker-compose.yml).
declare(strict_types=1);
foreach (['Config','Domain','Database'] as $c) require __DIR__."/../backend/src/$c.php";
$db=Banklord\Database::connect(); $fail=0; $base=getenv('BANKLORD_TEST_BASE')?:'http://127.0.0.1:8080';
$ok=function(bool $c,string $m) use(&$fail){ if(!$c){$fail++; echo "FAIL: $m\n";} };
$client=function() use($base){ $jar=''; $csrf='';
  return function(string $method,string $path,?array $body=null) use(&$jar,&$csrf,$base){
    $h="Content-Type: application/json\r\nAccept: application/json\r\n".($jar?"Cookie: $jar\r\n":'').($csrf?"X-CSRF-Token: $csrf\r\n":'');
    $ctx=stream_context_create(['http'=>['method'=>$method,'ignore_errors'=>true,'header'=>$h,'content'=>$body===null?'':json_encode($body)]]);
    $raw=file_get_contents($base.'/api/v1'.$path,false,$ctx);
    foreach($http_response_header as $line) if(preg_match('/^Set-Cookie: ([^;]+)/i',$line,$m)) $jar=$m[1];
    preg_match('~ (\d{3}) ~',$http_response_header[0],$m); $j=json_decode((string)$raw,true);
    if(isset($j['csrf'])) $csrf=$j['csrf']; return [(int)$m[1],$j]; }; };
$db->exec("INSERT INTO guilds (name,realm) VALUES ('Rechte','Everlook')"); $g=(int)$db->lastInsertId();
$users=[];
foreach (['member','bank_manager'] as $role) {
  $mail="rights$g-$role@x.invalid";
  $db->prepare("INSERT INTO users (email,password_hash,display_name) VALUES (?,?,?)")->execute([$mail,password_hash('test-password-123',PASSWORD_DEFAULT),$role]);
  $u=(int)$db->lastInsertId(); $db->prepare("INSERT INTO guild_memberships (guild_id,user_id,role) VALUES (?,?,?)")->execute([$g,$u,$role]);
  $c=$client(); $c('GET','/session'); [$st]=$c('POST','/login',['email'=>$mail,'password'=>'test-password-123']);
  $ok($st===200,"login $role ($st)"); $users[$role]=$c;
}
$m=$users['member']; $b=$users['bank_manager'];
[$st,$r]=$m('POST',"/guilds/$g/bridge-tokens",['label'=>'PC']);
$ok($st===403,"member cannot create scan token ($st)");
[$st,$r]=$m('POST',"/guilds/$g/bridge-tokens",['label'=>'PC','scope'=>'member.orders']);
$ok($st===201 && ($r['credential']['scope']??'')==='member.orders',"member creates personal token ($st)");
$memberTokenId=$r['credential']['id']??0;
[$st,$r]=$b('POST',"/guilds/$g/bridge-tokens",['label'=>'Bank-PC']);
$ok($st===201 && ($r['credential']['scope']??'')==='scan.stage',"manager creates scan token ($st)");
$scanId=$r['credential']['id']??0;
[$st,$r]=$m('GET',"/guilds/$g/bridge-tokens");
$ids=array_column($r['tokens']??[],'id');
$ok($st===200 && $ids===[$memberTokenId],'member sees only own token');
[$st,$r]=$m('DELETE',"/guilds/$g/bridge-tokens/$scanId");
$ok(($r['revoked']??null)===false,'member cannot revoke manager token');
[$st,$r]=$m('DELETE',"/guilds/$g/bridge-tokens/$memberTokenId");
$ok(($r['revoked']??null)===true,'member revokes own token');
[$st,$r]=$m('POST',"/guilds/$g/bridge-tokens",['label'=>'A','scope'=>'member.orders']);
[$st,$r]=$m('POST',"/guilds/$g/bridge-tokens",['label'=>'B','scope'=>'member.orders']);
[$st,$r]=$m('POST',"/guilds/$g/bridge-tokens",['label'=>'C','scope'=>'member.orders']);
$ok($st===409,"personal token limit ($st)");
// One account, several guilds: a signed-in member redeems an invitation of another guild.
$db->exec("INSERT INTO guilds (name,realm) VALUES ('Zweitgilde','Everlook')"); $g2=(int)$db->lastInsertId();
$inv=function(string $role) use($db,$g2){ $t='wgi1_'.bin2hex(random_bytes(32));
  $db->prepare('INSERT INTO guild_invitations (guild_id,created_by,token_hash,role,expires_at) VALUES (?,(SELECT MIN(id) FROM users),?,?,UTC_TIMESTAMP()+INTERVAL 48 HOUR)')->execute([$g2,hash('sha256',$t),$role]); return $t; };
$t1=$inv('bank_manager');
[$st,$r]=$m('POST','/invitations/redeem',['invitation'=>$t1]);
$ok($st===200 && ($r['guild']['guild_id']??0)===$g2 && ($r['guild']['name']??'')==='Zweitgilde','member joins a second guild ('.$st.' '.json_encode($r).')');
[$st,$r]=$m('GET','/guilds');$roles=[];foreach($r['guilds']??[] as $x)$roles[(int)$x['id']]=$x['role'];
$ok(($roles[$g]??'')==='member' && ($roles[$g2]??'')==='bank_manager','role per guild after joining '.json_encode($roles));
[$st,$r]=$m('POST','/invitations/redeem',['invitation'=>$t1]);
$ok(($r['error']??'')==='INVITE_EXPIRED_OR_USED','invitation works only once ('.$st.')');
$t2=$inv('member');[$st,$r]=$m('POST','/invitations/redeem',['invitation'=>$t2]);
$ok(($r['error']??'')==='ALREADY_MEMBER','already a member ('.$st.')');
$left=$db->prepare('SELECT redeemed_at FROM guild_invitations WHERE token_hash=?');$left->execute([hash('sha256',$t2)]);
$ok($left->fetchColumn()===null,'unused invitation stays valid when already a member');
$db->prepare("UPDATE guild_memberships SET status='disabled' WHERE guild_id=? AND user_id=(SELECT id FROM users WHERE email=?)")->execute([$g2,"rights$g-member@x.invalid"]);
[$st,$r]=$m('POST','/invitations/redeem',['invitation'=>$t2]);
$ok(($r['error']??'')==='MEMBERSHIP_DISABLED','a disabled member cannot re-enable himself ('.$st.')');
[$st,$r]=$m('POST','/invitations/redeem',['invitation'=>'quatsch']);
$ok(($r['error']??'')==='INVITE_EXPIRED_OR_USED','bad code rejected ('.$st.')');
$anon=$client();$anon('GET','/session');[$st]=$anon('POST','/invitations/redeem',['invitation'=>$t2]);
$ok($st===401,'not signed in: no joining ('.$st.')');
// Self sign-up of guild leaders: off by default, then account + guild in one step.
$db->exec("DELETE FROM login_attempts");
$db->exec("INSERT INTO site_settings (name,value) VALUES ('self_signup','0') ON DUPLICATE KEY UPDATE value='0'");
$su=$client();[$st,$r]=$su('GET','/session');$ok(($r['self_signup']??null)===false,'sign-up hidden by default');
$suf=bin2hex(random_bytes(4));$form=['guild_name'=>"Selbst$suf",'wow_flavor'=>'forever','realm'=>'','region'=>'EU','display_name'=>'Leiterin','email'=>"lead$suf@x.invalid",'password'=>'lang-genug-1234'];
[$st,$r]=$su('POST','/signup',$form);$ok(($r['error']??'')==='SIGNUP_CLOSED',"sign-up closed by default ($st)");
$db->exec("UPDATE site_settings SET value='1' WHERE name='self_signup'");
$db->exec("INSERT INTO site_settings (name,value) VALUES ('signups_per_day','500') ON DUPLICATE KEY UPDATE value='500'");
[$st,$r]=$su('GET','/session');$ok(($r['self_signup']??null)===true,'sign-up shown when switched on');
[$st,$r]=$su('POST','/signup',['password'=>'kurz']+$form);$ok(($r['error']??'')==='INVALID_REGISTRATION',"short password rejected ($st)");
[$st,$r]=$su('POST','/signup',$form);$sg=(int)($r['guild']['id']??0);
$ok($st===201 && ($r['guild']['realm']??'')==='Forever' && ($r['guild']['role']??'')==='admin',"forever guild signed up without realm ($st)");
[$st,$r]=$su('GET','/guilds');$ok(in_array($sg,array_map('intval',array_column($r['guilds']??[],'id')),true),'signed in and admin of the new guild');
$su2=$client();$su2('GET','/session');
[$st,$r]=$su2('POST','/signup',['email'=>"other$suf@x.invalid"]+$form);$ok(($r['error']??'')==='GUILD_EXISTS',"same guild twice rejected ($st)");
[$st,$r]=$su2('POST','/signup',['guild_name'=>"Andere$suf"]+$form);$ok(($r['error']??'')==='EMAIL_ALREADY_REGISTERED',"same e-mail twice rejected ($st)");
$db->exec("UPDATE site_settings SET value='0' WHERE name='signups_per_day'");
[$st,$r]=$su2('POST','/signup',['guild_name'=>"Dritte$suf",'email'=>"third$suf@x.invalid"]+$form);$ok(($r['error']??'')==='SIGNUP_DAILY_LIMIT',"daily limit ($st)");
// Locked guild: members are kept out, the Companion cannot upload, a non-operator cannot lock.
[$st]=$su('POST',"/operator/guilds/$sg/lock",['locked'=>true]);$ok($st===403,"guild admin cannot lock ($st)");
$db->prepare('UPDATE guilds SET locked_at=UTC_TIMESTAMP() WHERE id=?')->execute([$sg]);
[$st,$r]=$su('GET',"/guilds/$sg/bridge-tokens");$ok($st===423 && ($r['error']??'')==='GUILD_LOCKED',"locked guild closed ($st)");
$db->prepare('UPDATE guilds SET locked_at=NULL WHERE id=?')->execute([$sg]);
[$st]=$su('GET',"/guilds/$sg/bridge-tokens");$ok($st===200,"unlocked guild open again ($st)");
$db->exec("UPDATE site_settings SET value='0' WHERE name='self_signup'");$db->exec("UPDATE site_settings SET value='20' WHERE name='signups_per_day'");$db->exec("DELETE FROM login_attempts");
// Forgot password: one-time link by e-mail (dev: mails land in BANKLORD_MAIL_SINK).
$sink=getenv('BANKLORD_MAIL_SINK')?:'/tmp/banklord-mail.jsonl';@unlink($sink);$db->exec("DELETE FROM login_attempts");
$mails=function() use($sink){return is_file($sink)?array_map(fn($l)=>json_decode($l,true),file($sink,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)):[];};
$pw=$client();[$st,$r]=$pw('GET','/session');$ok(($r['password_reset']??null)===true,'forgot password offered when mail works');
[$st,$r]=$pw('POST','/password/forgot',['email'=>"nobody$suf@x.invalid"]);$ok($st===200 && count($mails())===0,"unknown address: same answer, no mail ($st)");
[$st,$r]=$pw('POST','/password/forgot',['email'=>"lead$suf@x.invalid"]);$ok($st===200 && count($mails())===0,"placeholder .invalid address gets no mail ($st)");
$mail="reset$suf@example.org";$db->prepare("INSERT INTO users (email,password_hash,display_name) VALUES (?,?,?)")->execute([$mail,password_hash('altes-passwort-123',PASSWORD_DEFAULT),'Vergesslich']);$ru=(int)$db->lastInsertId();
[$st,$r]=$pw('POST','/password/forgot',['email'=>strtoupper($mail)]);$mm=$mails();
$ok($st===200 && count($mm)===1 && $mm[0]['to']===$mail && preg_match('/#reset=(bpr1_[a-f0-9]{64})/',$mm[0]['body'],$tm),"reset link mailed ($st)");
$tok=$tm[1]??'';
[$st,$r]=$pw('POST','/password/reset',['token'=>'bpr1_'.str_repeat('0',64),'password'=>'neues-passwort-123']);$ok(($r['error']??'')==='RESET_INVALID',"unknown link rejected ($st)");
[$st,$r]=$pw('POST','/password/reset',['token'=>$tok,'password'=>'kurz']);$ok(($r['error']??'')==='WEAK_PASSWORD',"short password rejected ($st)");
[$st,$r]=$pw('POST','/password/reset',['token'=>$tok,'password'=>'neues-passwort-123']);$ok($st===200 && ($r['user_id']??0)===$ru,"password reset and signed in ($st)");
[$st,$r]=$pw('POST','/password/reset',['token'=>$tok,'password'=>'noch-ein-passwort-1']);$ok(($r['error']??'')==='RESET_INVALID',"link works only once ($st)");
$nl=$client();$nl('GET','/session');[$st]=$nl('POST','/login',['email'=>$mail,'password'=>'neues-passwort-123']);$ok($st===200,"login with the new password ($st)");
// SMTP settings: operator only, password write-only and stored encrypted.
[$st]=$m('GET','/operator/mail');$ok($st===403,"member cannot see mail settings ($st)");
$db->prepare('UPDATE users SET is_operator=1 WHERE id=?')->execute([$ru]);
[$st,$r]=$nl('PUT','/operator/mail',['host'=>'bad host','port'=>465,'user'=>'x@example.org']);$ok(($r['error']??'')==='INVALID_MAIL_SETTINGS',"bad mail settings rejected ($st)");
[$st,$r]=$nl('PUT','/operator/mail',['host'=>'smtp.example.org','port'=>587,'user'=>'noreply@example.org','password'=>'geheim-smtp-pass']);
$ok($st===200 && ($r['mail']['has_password']??false)===true && !array_key_exists('password',$r['mail']??[]) && !str_contains(json_encode($r),'geheim-smtp-pass'),"mail settings saved, password never returned ($st)");
$enc=(string)$db->query("SELECT value FROM site_settings WHERE name='mail_pass'")->fetchColumn();$ok($enc!=='' && !str_contains($enc,'geheim'),'smtp password stored encrypted');
@unlink($sink);[$st]=$nl('POST','/operator/mail/test');$mm=$mails();$ok($st===200 && ($mm[0]['to']??'')===$mail,"test mail to the operator ($st)");
// Operator manages accounts: list, lock (session ends, login refused, Companion stops), reset link; never other operators.
[$st,$r]=$nl('GET','/operator/accounts?q='.urlencode("lead$suf"));$acc=$r['accounts'][0]??[];
$ok($st===200 && ($r['total']??0)===1 && ($acc['display_name']??'')==='Leiterin' && !isset($acc['password_hash']),"operator lists accounts ($st)");
$db->prepare("INSERT INTO characters (user_id,guild_id,name,realm) VALUES (?,?,?,'Forever')")->execute([$lid=(int)$acc['id'],$sg,"Zwerg$suf"]);
[$st,$r]=$nl('GET','/operator/accounts?q='.urlencode("Zwerg$suf"));$ok(($r['total']??0)===1 && ($r['accounts'][0]['characters']??'')==="Zwerg$suf","account found by character name ($st)");
[$st]=$m('GET','/operator/accounts');$ok($st===403,"member cannot list accounts ($st)");
$lid=(int)$acc['id'];
[$st,$r]=$nl('POST',"/operator/accounts/$ru/lock",['locked'=>true]);$ok(($r['error']??'')==='ACCOUNT_PROTECTED',"operator cannot lock himself ($st)");
[$st,$r]=$nl('POST',"/operator/accounts/$lid/lock",['locked'=>true]);$ok($st===200 && ($r['locked']??null)===true,"account locked ($st)");
[$st,$r]=$su('GET','/guilds');$ok($st===401 && ($r['error']??'')==='ACCOUNT_LOCKED',"running session of a locked account ends ($st)");
$lc=$client();$lc('GET','/session');[$st,$r]=$lc('POST','/login',['email'=>"lead$suf@x.invalid",'password'=>'lang-genug-1234']);$ok($st===403 && ($r['error']??'')==='ACCOUNT_LOCKED',"locked account cannot sign in ($st)");
[$st]=$nl('POST',"/operator/accounts/$lid/lock",['locked'=>false]);
[$st]=$lc('POST','/login',['email'=>"lead$suf@x.invalid",'password'=>'lang-genug-1234']);$ok($st===200,"unlocked account signs in again ($st)");
[$st,$r]=$nl('POST',"/operator/accounts/$lid/reset",['send'=>false]);$ok($st===200 && preg_match('/#reset=(bpr1_[a-f0-9]{64})$/',$r['link']??'',$lk),"operator gets a reset link to pass on ($st)");
[$st]=$lc('POST','/password/reset',['token'=>$lk[1]??'','password'=>'vom-betreiber-123']);$ok($st===200,"reset link from operator works ($st)");
@unlink($sink);[$st,$r]=$nl('POST',"/operator/accounts/$lid/reset",['send'=>true]);$ok(($r['error']??'')==='MAIL_NOT_POSSIBLE',"no reset mail to a reserved .invalid address ($st)");
$db->prepare('UPDATE users SET is_operator=0 WHERE id=?')->execute([$ru]);$db->exec("DELETE FROM site_settings WHERE name LIKE 'mail\\_%' OR name='site_url'");@unlink($sink);$db->exec("DELETE FROM login_attempts");
echo $fail?"FAILED ($fail)\n":"PASS: token rights over HTTP session\n"; exit($fail?1:0);
